11: /// mỗi lần ghi, resolve LẠI toàn bộ reference của graph và ghi đè, không diff và không đọc FK cũ.
12: /// <para>
13: /// Policy này KHÔNG khai báo tên trường snapshot. Nguồn khai báo duy nhất là
14: /// <see cref="SnapshotReferenceAttribute"/> trên entity; ở đây chỉ liệt kê các node của graph.
15: /// </para>
16: /// </summary>
17: public sealed class DeliveryPackagingSnapshotPolicy(SnapshotPolicyEngine engine)
18: {
19:     public Task<Result<SnapshotPolicyContext>> CollectAsync(DeliveryPackaging graph, CancellationToken cancellationToken) =>
20:         engine.CollectGraphAsync(EnumerateNodes(graph), cancellationToken);
21: 
22:     /// <summary>Dùng cho đường ghi chỉ chạm một phần aggregate (cập nhật theo tab).</summary>
23:     public Task<Result<SnapshotPolicyContext>> CollectNodesAsync(IEnumerable<object> nodes, CancellationToken cancellationToken) =>
24:         engine.CollectGraphAsync(nodes, cancellationToken);
25: 
26:     public void Apply(DeliveryPackaging entity, SnapshotPolicyContext context) =>
27:         SnapshotPolicyEngine.ApplyGraph(context, EnumerateNodes(entity));
28: 
29:     /// <summary>
30:     /// Mọi node mang <see cref="SnapshotReferenceAttribute"/> của aggregate. Dùng chung cho cả collect
31:     /// lẫn apply nên hai pha không thể phủ sóng lệch nhau.
32:     /// </summary>
33:     public static IEnumerable<object> EnumerateNodes(DeliveryPackaging packaging)
34:     {
35:         yield return packaging;
36:         foreach (var node in Alive(packaging.Goods)) yield return node;
37:         foreach (var node in Alive(packaging.Details)) yield return node;
38:         foreach (var node in Alive(packaging.SemiFinishedGoods)) yield return node;
39:         foreach (var node in Alive(packaging.Processes)) yield return node;
40:         foreach (var node in Alive(packaging.RawMats)) yield return node;
41:     }
