18:         string kind,
19:         IReadOnlySet<Guid> ids,
20:         CancellationToken cancellationToken)
21:     {
22:         if (ids.Count == 0)
23:         {
24:             return new Dictionary<Guid, SnapshotValue>();
25:         }
26: 
27:         var item = new SnapshotRefRequestItem { Kind = kind };
28:         item.Ids.AddRange(ids.Select(id => id.ToString()));
29: 
30:         var request = new ResolveSnapshotReferencesRequest();
