"    public override async Task<Result<FinishedGoodsPackingDto>> Update(Guid id, UpdateFinishedGoodsPackingDto dto)
    {
        if (dto.Details?.Count > 0)
        {
            var lockResult = await ValidateNoLockedDetailsAsync(
                dto.Details.Select(d => d.MechanicalPackingListDetailId));
            if (!lockResult.IsSuccess)
                return Result<FinishedGoodsPackingDto>.Failure(lockResult.Message, lockResult.StatusCode);
        }

        if (dto.MechanicalPackingListId == Guid.Empty)
        {
            var existingSummary = await _repository.Query()
                .Where(p => p.Id == id)
                .Select(p => new { p.MechanicalPackingListId, p.FinishedGoodId, p.ModelId, p.DesignModelId, p.PackingCodesId })
                .FirstOrDefaultAsync(RequestAborted);
            if (existingSummary != null)
            {
                dto.MechanicalPackingListId = existingSummary.MechanicalPackingListId;
                dto.FinishedGoodId ??= existingSummary.FinishedGoodId;
                dto.ModelId ??= existingSummary.ModelId;
                dto.DesignModelId ??= existingSummary.DesignModelId;
                if (dto.PackingCodesId == Guid.Empty) dto.PackingCodesId = existingSummary.PackingCodesId;
            }
        }

        var graph = await BuildSnapshotGraphAsync(dto, RequestAborted);

        return await _snapshotLifecycle.ExecuteAsync<FinishedGoodsPacking, FinishedGoodsPackingDto>(
            ct => _snapshotPolicy.CollectAsync(graph, ct),
            () => base.Update(id, dto),
            RequestAborted);
    }"

