#### Trường hợp 2: Xử lý mảng bằng `Promise.all` thay vì `forEach`
`Array.prototype.forEach` **hoàn toàn không chờ `await`**.

```typescript
//  SAI: forEach sẽ chạy vèo qua mà không đợi từng file upload xong!
files.forEach(async (file) => {
    await uploadFile(file);
});
console.log('Xong!'); // In ra 'Xong!' trong khi file VẪN ĐANG upload dở!

//  ĐÚNG CÁCH 1: Chạy song song tất cả các file (Nhanh nhất)
await Promise.all(files.map(async (file) => {
    await uploadFile(file);
}));
console.log('Tất cả file đã upload xong');

//  ĐÚNG CÁCH 2: Muốn chạy lần lượt từng file một (Tuần tự)
for (const file of files) {
    await uploadFile(file);
}
console.log('Tất cả file đã upload xong');
```

